'use strict';
const reportTabs=[['Analytics','Savings & credit'],['Transactions','Transactions & status'],['Work','Staff work reports'],['Assembly','Meeting & assembly'],['District','District assemblies'],['Cluster','Branch cluster meetings']];
const reportDetailLabels={location:'Venue / cluster',eligible:'Eligible participants',attended:'Attendees',delegates:'Elected delegates',resolutions:'Resolutions / decisions',committee:'Committee / auditor',assets:'Reported assets',provisions:'Reported loan-loss provisions',budget:'Proposed budget',welfare:'Member benefit / welfare updates'};
function canUseReports(){return ['Admin','DM','BM','Staff'].includes(S.role);}
async function loadReports(){S.reports=[];S.reportTypes=[];S.reportEvents=[];S.workReports=[];S.workReportEvents=[];S.reportsReady=false;S.reportsError='';if(!canUseReports())return;try{[S.reportTypes,S.reports,S.reportEvents,S.workReports,S.workReportEvents]=await Promise.all([allRows('/rest/v1/occci_report_types?select=*&order=category,name'),S.role==='Staff'?[]:allRows('/rest/v1/occci_reports?select=*&order=updated_at.desc,id'),S.role==='Staff'?[]:allRows('/rest/v1/occci_report_events?select=*&order=created_at.desc,id.desc'),allRows('/rest/v1/occci_work_reports?select=*&order=updated_at.desc,id'),allRows('/rest/v1/occci_work_report_events?select=*&order=created_at.desc,id.desc')]);S.reportsReady=true;}catch(err){S.reportsError=err.message;}}

function reportScopeLabel(r){return r.branch_id?bn(r.branch_id)+' branch':r.district?'District '+r.district:'Cooperative';}
function canWriteReport(r){return canUseReports()&&(S.role==='Admin'||S.role==='DM'&&r.district===S.assignment?.district||S.role==='BM'&&r.branch_id===S.assignment?.branch_id);}
function reportBranches(){return allowedBranches().filter(b=>(S.reportDistrict==='all'||b.district===Number(S.reportDistrict))&&(S.scope==='all'||b.id===S.scope));}
function reportDistrictChanged(value){S.reportDistrict=value;S.reportBranch='all';S.reportPage=1;render();}
function reportFilters(showYear=true){const branches=reportBranches();return `<div class="report-filters"><label>District<select onchange="reportDistrictChanged(this.value)">${memberFilterOptions([['all','All assigned districts'],...[...new Set(allowedBranches().map(b=>b.district))].sort().map(d=>[d,'District '+d])],S.reportDistrict)}</select></label><label>Branch<select onchange="S.reportBranch=this.value;S.reportPage=1;render()">${memberFilterOptions([['all','All assigned branches'],...branches.map(b=>[b.id,b.name])],S.reportBranch)}</select></label>${showYear?`<label>Reporting year<input type="number" min="2000" max="2100" value="${e(S.reportYear)}" onchange="S.reportYear=this.value;S.reportPage=1;render()"></label><label>Status<select onchange="S.reportStatus=this.value;S.reportPage=1;render()">${memberFilterOptions([['all','All statuses'],...['Draft','For review','Approved','Returned','Filed','Archived'].map(v=>[v,v])],S.reportStatus)}</select></label>`:''}</div>`;}
function selectedReportRows(category){return S.reports.filter(r=>{if(S.reportTypes.find(t=>t.id===r.type_id)?.category!==category)return false;if(S.reportStatus==='Archived'?!r.archived_at:r.archived_at)return false;if(S.reportStatus!=='all'&&S.reportStatus!=='Archived'&&r.status!==S.reportStatus)return false;if(S.reportYear&&(r.period_start.slice(0,4)>S.reportYear||r.period_end.slice(0,4)<S.reportYear))return false;const branch=S.reportBranch!=='all'?S.reportBranch:S.scope;return (S.reportDistrict==='all'||r.district===Number(S.reportDistrict))&&(branch==='all'||r.branch_id===branch);});}
function reportsView(){if(S.role==='Staff')return staffWorkView();if(!canUseReports())return empty('Reports access','Reports are available to Admin, District Managers and Branch Managers.');return heading(S.role==='Admin'?'Cooperative reports':S.role==='DM'?'District reports':'Branch reports','Verified account analytics and cooperative reporting records.')+`<nav class="report-tabs" aria-label="Report sections">${reportTabs.map(([v,label])=>`<button type="button" onclick="S.reportTab='${v}';S.reportPage=1;render()" ${S.reportTab===v?'aria-current="page"':''}>${label}</button>`).join('')}</nav>${S.reportTab==='Analytics'?financialAnalyticsView():S.reportTab==='Transactions'?transactionReportsView():S.reportTab==='Work'?staffWorkView(false):reportRegisterView()}`;}
function financialAnalytics(){const branches=reportBranches().filter(b=>S.reportBranch==='all'||b.id===S.reportBranch),ids=new Set(branches.map(b=>b.id)),members=S.profiles.filter(p=>ids.has(p.branch_id)&&(p.registration_kind!=='Staff'||S.financials.some(f=>f.member_id===p.id))&&!p.archived_at);const groups=branches.map(b=>{const people=members.filter(p=>p.branch_id===b.id),fin=people.map(p=>S.financials.find(f=>f.member_id===p.id)).filter(Boolean);return {district:b.district,branch:b.name,members:people.length,active:people.filter(p=>p.membership_status==='Active').length,pending:people.filter(p=>p.membership_status==='Pending verification').length,verified:fin.length,savings:fin.reduce((n,f)=>n+Number(f.savings),0),loans:fin.reduce((n,f)=>n+Number(f.loan_balance),0),overdue:fin.filter(f=>f.loan_status==='Overdue').reduce((n,f)=>n+Number(f.loan_balance),0),oldest:fin.length?fin.map(f=>f.as_of).sort()[0]:'',newest:fin.length?fin.map(f=>f.as_of).sort().at(-1):''};});const total=groups.reduce((n,g)=>{for(const k of ['members','active','pending','verified','savings','loans','overdue'])n[k]+=g[k];return n;},{members:0,active:0,pending:0,verified:0,savings:0,loans:0,overdue:0});const districts=[...new Set(groups.map(g=>g.district))].map(d=>groups.filter(g=>g.district===d).reduce((n,g)=>{for(const k of ['members','active','verified','savings','loans','overdue'])n[k]+=g[k];return n;},{district:d,members:0,active:0,verified:0,savings:0,loans:0,overdue:0}));return {groups,districts,total};}
function branchSummaryChanged(district){if(!financialAnalytics().groups.some(g=>g.district===Number(district)))return;S.branchSummaryDistrict=Number(district);render();}
function branchSummaryView(groups){
 const districts=[...new Set(groups.map(g=>g.district))].sort((a,b)=>a-b);
 if(!districts.includes(S.branchSummaryDistrict))S.branchSummaryDistrict=districts[0]??null;
 const rows=groups.filter(g=>g.district===S.branchSummaryDistrict);
 return `<section class="branch-summary spacer" aria-labelledby="branchSummaryTitle"><h2 id="branchSummaryTitle">Branch summary</h2>${districts.length?`<nav class="branch-district-tabs" aria-label="Branch summary districts">${districts.map(d=>{const count=groups.filter(g=>g.district===d).length;return `<button type="button" id="branchDistrict${d}" onclick="branchSummaryChanged(${d})" aria-pressed="${d===S.branchSummaryDistrict}" aria-controls="branchSummaryTable">District ${d}<span>${count} ${count===1?'branch':'branches'}</span></button>`;}).join('')}</nav>`:''}<div id="branchSummaryTable" ${districts.length?`aria-labelledby="branchDistrict${S.branchSummaryDistrict}"`:''}>${analyticsTable(rows,true)}</div></section>`;
}
function financialAnalyticsView(){const {groups,districts,total}=financialAnalytics();return `<section class="card reports-panel">${reportFilters(false)}<div class="report-actions"><p class="smalltext">Latest approved balances · ${total.verified} of ${total.members} member records verified · Generated ${e(today())}</p><button type="button" class="outline small" onclick="exportFinancialReport()">${icon('file')} Export CSV</button></div><div class="report-metrics">${[['Verified savings',money(total.savings)],['Outstanding loans',money(total.loans)],['Overdue loan balances',money(total.overdue)],['Active / pending members',total.active+' / '+total.pending]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><h2>District summary</h2>${analyticsTable(districts,false)}${branchSummaryView(groups)}<p class="hint">Balances are current verified snapshots, not historical turnover or audited financial statements. Overdue balances use the approved loan status. Assets, provisions, income and collection efficiency require original accounting records.</p></section>`;}
function analyticsTable(rows,branches){return `<div class="table-wrap report-table"><table><thead><tr><th>${branches?'Branch':'District'}</th><th>Members</th><th>Active</th><th>Verified</th><th>Savings</th><th>Loans</th><th>Overdue</th>${branches?'<th>Record dates</th>':''}</tr></thead><tbody>${rows.map(g=>`<tr><td>${branches?e(g.branch):'District '+g.district}</td><td>${g.members}</td><td>${g.active}</td><td>${g.verified}</td><td>${money(g.savings)}</td><td>${money(g.loans)}</td><td>${money(g.overdue)}</td>${branches?`<td>${e(g.oldest||'No verified records')}${g.newest&&g.newest!==g.oldest?' – '+e(g.newest):''}</td>`:''}</tr>`).join('')||`<tr><td colspan="${branches?8:7}">No branches match your filters.</td></tr>`}</tbody></table></div>`;}
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function downloadCsv(rows,name){const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportFinancialReport(){if(!canUseReports())return;const {groups}=financialAnalytics();downloadCsv([['District','Branch','Members','Active','Pending','Verified records','Savings balance','Outstanding loans','Overdue loan balances','Oldest record date','Newest record date','Generated'],...groups.map(g=>[g.district,g.branch,g.members,g.active,g.pending,g.verified,g.savings,g.loans,g.overdue,g.oldest,g.newest,today()])],'OCCCI-verified-balances-'+today()+'.csv');}
function reportRegisterView(){if(!S.reportsReady)return `<section class="card"><h2>Report register needs activation</h2><p>${e(S.reportsError||'The report tables are not available yet.')}</p><p class="hint">Existing savings and credit analytics remain available. Apply the Reports migration in the OCCCI database, then refresh.</p>${button('Retry','reload()','primary')}</section>`;const category=S.reportTab,rows=selectedReportRows(category),types=S.reportTypes.filter(t=>t.active&&t.category===category),pages=Math.max(1,Math.ceil(rows.length/20));S.reportPage=Math.min(Math.max(1,S.reportPage),pages);const show=rows.slice((S.reportPage-1)*20,S.reportPage*20),canCreate=category!=='Compliance'||S.role==='Admin';return `<section class="card reports-panel">${reportFilters()}<div class="report-actions"><p class="smalltext">${rows.length} report records · 20 per page</p><div class="flex"><button type="button" class="outline small" onclick="exportReportRegister()">Export CSV</button>${canCreate?`<button type="button" class="primary small" onclick="reportEditDialog()">${icon('plus')} New report</button>`:''}</div></div>${category==='Compliance'?`<p class="hint">Prepare and track annual filing records here. Record the official acknowledgement after submitting through CDA’s reporting system. Filing dates and applicability are set by the cooperative. <a href="https://cda.gov.ph/wp-content/uploads/2025/03/MC-2025-02-with-annexes.pdf" target="_blank" rel="noopener noreferrer">CDA reporting guidance</a></p>`:''}<details class="report-checklist"><summary>Report checklist · ${types.length} types</summary><ul>${types.map(t=>{const found=rows.filter(r=>r.type_id===t.id&&!r.archived_at);return `<li><span><strong>${e(t.name)}</strong><small>${e(t.guidance)}</small></span><span>${found.some(r=>r.status==='Filed')?'Filed':found.some(r=>r.status==='Approved')?'Approved':found.length?'In progress':'No record'}</span></li>`;}).join('')}</ul></details><ul class="request-list">${show.map(r=>`<li class="request-list-row"><div class="request-list-info"><div class="request-list-title"><h2>${e(r.title)}</h2>${statusPill(r.archived_at?'Archived':r.status)}</div><p class="request-list-meta">${e(reportScopeLabel(r))} · ${e(r.period_start)} – ${e(r.period_end)}${r.due_date?' · Due '+e(r.due_date):''}${r.due_date<today()&&!['Filed'].includes(r.status)&&!r.archived_at?' · Past due':''}</p></div><button type="button" class="outline request-list-action" onclick="reportDialog('${r.id}')">${icon('file')} View</button></li>`).join('')}</ul>${rows.length?'':empty('No report records','Create a report and attach its original records.')}<nav class="pagination" aria-label="Report pages"><span>Page ${S.reportPage} of ${pages}</span><div class="flex"><button type="button" class="outline small" onclick="S.reportPage--;render()" ${S.reportPage===1?'disabled':''}>Previous</button><button type="button" class="outline small" onclick="S.reportPage++;render()" ${S.reportPage===pages?'disabled':''}>Next</button></div></nav></section>`;}
function exportReportRegister(){if(!canUseReports())return;downloadCsv([['Title','Type','Scope','Period start','Period end','Meeting date','Due date','Status','Filed on','Acknowledgement','Summary'],...selectedReportRows(S.reportTab).map(r=>[r.title,S.reportTypes.find(t=>t.id===r.type_id)?.name,reportScopeLabel(r),r.period_start,r.period_end,r.meeting_date,r.due_date,r.archived_at?'Archived':r.status,r.filed_on,r.filing_reference,r.summary])],'OCCCI-'+S.reportTab+'-reports-'+S.reportYear+'.csv');}
function reportEditDialog(id=''){const r=S.reports.find(r=>r.id===id);if(!canUseReports()||r&&!canWriteReport(r))return;const category=r?S.reportTypes.find(t=>t.id===r.type_id)?.category:S.reportTab,types=S.reportTypes.filter(t=>t.active&&t.category===category);if(!types.length)return toast('No active report types in this section.');const type=r?.type_id||types[0].id,scope=r?(r.branch_id?'branch':r.district?'district':'cooperative'):category==='Compliance'?'cooperative':category==='Cluster'||S.role==='BM'?'branch':category==='District'||S.role==='DM'?'district':'cooperative',d=r?.district||S.assignment?.district||S.branches.find(b=>b.id===S.assignment?.branch_id)?.district||Number(S.reportDistrict==='all'?allowedBranches()[0]?.district:S.reportDistrict),b=r?.branch_id||S.assignment?.branch_id||S.reportBranch,year=/^20\d\d$/.test(S.reportYear)?S.reportYear:String(new Date().getFullYear());openModal(id?'Edit report':'New report',`<form class="report-edit-form" onsubmit="event.preventDefault();saveReport(this,'${id}')"><div class="form-grid"><label class="full">Report type<select name="type_id">${memberFilterOptions(types.map(t=>[t.id,t.name]),type)}</select></label>${field('Title','title',r?.title||types[0].name)}<label>Scope<select id="reportScope" name="scope" onchange="reportFormScopeChanged()">${memberFilterOptions((category==='Compliance'?['cooperative']:category==='District'?['district']:category==='Cluster'?['branch']:S.role==='Admin'?['cooperative','district','branch']:S.role==='DM'?['district','branch']:['branch']).map(v=>[v,v==='cooperative'?'Cooperative':v==='district'?'District':'Branch / cluster']),scope)}</select></label><label id="reportDistrictField">District<select name="district" id="reportFormDistrict" onchange="reportFormDistrictChanged()">${memberFilterOptions([...new Set(allowedBranches().map(b=>b.district))].sort().map(d=>[d,'District '+d]),d)}</select></label><label id="reportBranchField">Branch<select name="branch_id" id="reportFormBranch">${memberFilterOptions(allowedBranches().filter(x=>x.district===d).map(x=>[x.id,x.name]),b)}</select></label>${field('Period start','period_start',r?.period_start||year+'-01-01','date')}${field('Period end','period_end',r?.period_end||year+'-12-31','date')}${field('Meeting date (optional)','meeting_date',r?.meeting_date||'','date',false)}${field('Due date (optional)','due_date',r?.due_date||'','date',false)}<label class="full">Summary / proceedings<textarea name="summary" maxlength="10000" rows="3">${e(r?.summary||'')}</textarea></label></div><details class="report-extra"><summary>Attendance, decisions and reported figures</summary><div class="form-grid">${Object.entries(reportDetailLabels).map(([key,label])=>field(label,key,r?.details?.[key]??'',['eligible','attended'].includes(key)?'number':'text',false)).join('')}</div></details><div class="form-grid spacer">${supportingDocumentsPicker()}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required rows="2"></textarea></label></div><div class="report-form-actions"><button type="submit" class="primary">Save draft</button><p class="hint">Submit the saved report for review when the summary and source documents are ready.</p></div></form>`);const form=$('modalContent').querySelector('form');form._supportingDocuments=(r?.documents||[]).slice();renderSelectedDocuments(form);reportFormScopeChanged();}
function reportFormScopeChanged(){const scope=$('reportScope').value,df=$('reportDistrictField'),bf=$('reportBranchField');df.hidden=scope==='cooperative';bf.hidden=scope!=='branch';df.querySelector('select').disabled=scope==='cooperative';bf.querySelector('select').disabled=scope!=='branch';}
function reportFormDistrictChanged(){const d=Number($('reportFormDistrict').value);$('reportFormBranch').innerHTML=memberFilterOptions(allowedBranches().filter(b=>b.district===d).map(b=>[b.id,b.name]),'');}
async function saveReport(form,id){const btn=form.querySelector('[type=submit]'),label=btn.textContent;btn.disabled=true;try{const v=Object.fromEntries(new FormData(form)),files=selectedDocuments(form).slice();if(files.length)validateDocuments(files);if(v.period_end<v.period_start)throw Error('Period end must follow period start.');if(v.eligible!==''&&v.attended!==''&&Number(v.attended)>Number(v.eligible))throw Error('Attendance cannot exceed eligible participants.');form.dataset.uploading='true';renderSelectedDocuments(form);const docs=[];for(const f of files){btn.textContent=`Saving files ${docs.length+1} / ${files.length}`;docs.push(f.path?f:{path:await upload('occci-reports',f),name:f.name,size:f.size,type:f.type||'application/octet-stream'});}const details=Object.fromEntries(Object.keys(reportDetailLabels).filter(k=>v[k]!==''&&v[k]!=null).map(k=>[k,['eligible','attended'].includes(k)?Number(v[k]):v[k]]));const report=S.reports.find(r=>r.id===id);const result=await rpc('occci_save_report',{target:id||null,expected_revision:report?.revision||0,values_json:{type_id:v.type_id,title:v.title,branch_id:v.scope==='branch'?v.branch_id:null,district:v.scope==='cooperative'?null:Number(v.district),period_start:v.period_start,period_end:v.period_end,meeting_date:v.meeting_date||null,due_date:v.due_date||null,summary:v.summary,details,documents:docs},reason:v.reason});closeModal();await loadReports();render();if(result)reportDialog(result);toast('Report saved and logged.');}catch(err){$('actionMessage').textContent=err.message;}finally{form.dataset.uploading='false';renderSelectedDocuments(form);btn.disabled=false;btn.textContent=label;}}
function reportDialog(id){const r=S.reports.find(r=>r.id===id);if(!r||!canUseReports())return;const write=canWriteReport(r),review=write&&(r.created_by!==S.session.user.id||S.role==='Admin'&&!r.district&&!r.branch_id)&&r.status==='For review';const actions=r.archived_at?(write?['Restore']:[]):[...(write&&['Draft','Returned'].includes(r.status)?['Edit','Submit']:[]),...(review?['Approve','Return']:[]),...(write&&r.status==='Approved'?['File']:[]),...(write?['Archive']:[])];openModal(r.title,`<div class="report-detail-head">${statusPill(r.archived_at?'Archived':r.status)}<span>${e(reportScopeLabel(r))}</span><button type="button" class="outline small" onclick="reportHistoryDialog('${id}')">${icon('clock')} Activity logs</button></div><dl class="details-list">${detail('Report type',e(S.reportTypes.find(t=>t.id===r.type_id)?.name||r.type_id))}${detail('Period',e(r.period_start)+' – '+e(r.period_end))}${r.meeting_date?detail('Meeting date',e(r.meeting_date)):''}${r.due_date?detail('Due date',e(r.due_date)):''}${r.filed_on?detail('Filed on',e(r.filed_on)):''}${r.filing_reference?detail('Acknowledgement',e(r.filing_reference)):''}${Object.entries(r.details||{}).map(([k,v])=>detail(e(reportDetailLabels[k]||k),e(v))).join('')}</dl><h3>Summary / proceedings</h3><p class="content-body">${e(r.summary||'Draft summary not recorded.')}</p>${r.review_note?`<p class="hint">Review notes: ${e(r.review_note)}</p>`:''}${r.documents.length?`<h3>Original supporting documents</h3><ul class="document-list">${r.documents.map((d,i)=>`<li><button type="button" class="outline small" onclick="viewReportDocument('${id}',${i})">${icon('file')}${e(d.name)}</button><small>${(d.size/1024/1024).toFixed(2)} MB</small></li>`).join('')}</ul>`:''}<div class="priority-actions">${actions.map(a=>`<button type="button" class="${a==='Archive'?'danger':'outline'}" onclick="${a==='Edit'?`reportEditDialog('${id}')`:`reportDecisionDialog('${id}','${a}')`}">${a==='File'?'Record filing':a==='Submit'?'Submit for review':a}</button>`).join('')}</div><p class="hint">Review approval records an internal decision. Recording a filing does not submit anything to CDA.</p>`);}
function reportDecisionDialog(id,decision){const r=S.reports.find(r=>r.id===id);openModal(decision==='File'?'Record official filing':decision+' report',`<form onsubmit="event.preventDefault();transitionReport(this,'${id}','${decision}',${r.revision})">${decision==='File'?`${field('Actual filing date','filed_date',today(),'date')}<label>Acknowledgement / receipt reference<input name="reference" minlength="3" maxlength="300" required></label>`:''}<label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="hint">${decision==='Archive'?'This hides the report from the active register. Its records and logs are retained, and it can be restored.':decision==='File'?'Use the acknowledgement from the official submission destination.':'This action is recorded in the report activity log.'}</p><button type="submit" class="primary">Confirm ${decision.toLowerCase()}</button></form>`);}
async function transitionReport(form,id,decision,revision){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const v=Object.fromEntries(new FormData(form));await rpc('occci_report_transition',{target:id,decision,expected_revision:revision,reason:v.reason,filed_date:v.filed_date||null,reference:v.reference||null});closeModal();await loadReports();render();reportDialog(id);toast('Report action recorded.');}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
function reportHistoryDialog(id){const rows=S.reportEvents.filter(a=>a.report_id===id);openModal('Report activity logs',`<button type="button" class="outline small" onclick="reportDialog('${id}')">Back to report</button><div class="spacer">${auditRows(rows,'report:'+id)}</div>`);}
async function viewReportDocument(id,index){const file=S.reports.find(r=>r.id===id)?.documents[index];if(!file)return;try{const url=await signedUrl('occci-reports',file.path),a=document.createElement('a');a.href=url+(url.includes('?')?'&':'?')+'download='+encodeURIComponent(file.name);a.download=file.name;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(err){$('actionMessage').textContent=err.message;}}

const workMetricLabels={registrations:'New member registrations',account_updates:'Account / profile updates',savings_collections:'Actual savings collected (₱)',loan_releases:'Actual loans released (₱)',loan_repayments:'Actual loan repayments (₱)',followups:'Collection / member follow-ups'};
function reportPeriod(frequency=S.reportFrequency,on=S.reportOn){const d=new Date(on+'T00:00:00Z');if(!Number.isFinite(d.getTime()))return {start:today(),end:today()};const iso=d=>d.toISOString().slice(0,10);if(frequency==='Weekly'){d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const start=iso(d);d.setUTCDate(d.getUTCDate()+6);return {start,end:iso(d)};}if(frequency==='Monthly')return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)))};return {start:on,end:on};}
function reportPeriodControls(){const {start,end}=reportPeriod();return `<div class="period-filters"><label>Frequency<select onchange="S.reportFrequency=this.value;S.reportPage=1;render()">${memberFilterOptions(['Daily','Weekly','Monthly'].map(v=>[v,v]),S.reportFrequency)}</select></label><label>Date in period<input type="date" value="${e(S.reportOn)}" onchange="S.reportOn=this.value;S.reportPage=1;render()"></label><span>${e(start)} – ${e(end)}</span></div>`;}
function filteredWorkReports(){const {start,end}=reportPeriod();return S.workReports.filter(w=>w.frequency===S.reportFrequency&&w.period_start===start&&w.period_end===end&&(S.reportDistrict==='all'||w.district===Number(S.reportDistrict))&&(S.reportBranch==='all'||w.branch_id===S.reportBranch)&&(S.scope==='all'||w.branch_id===S.scope));}
function activityReportDate(value){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');}
function transactionReportData(){const {start,end}=reportPeriod(),ids=new Set(reportBranches().filter(b=>S.reportBranch==='all'||b.id===S.reportBranch).map(b=>b.id));const events=S.audit.filter(a=>ids.has(a.branch_id)&&activityReportDate(a.created_at)>=start&&activityReportDate(a.created_at)<=end);const reports=S.workReports.filter(w=>ids.has(w.branch_id)&&w.frequency===S.reportFrequency&&w.period_start===start&&w.period_end===end);const approved=reports.filter(w=>w.status==='Approved');const groups=[...ids].map(id=>{const rows=events.filter(a=>a.branch_id===id),work=approved.filter(w=>w.branch_id===id);return {branch:id,district:S.branches.find(b=>b.id===id)?.district,events:rows.length,staffReports:work.length,collections:work.reduce((n,w)=>n+Number(w.metrics.savings_collections||0),0),releases:work.reduce((n,w)=>n+Number(w.metrics.loan_releases||0),0),repayments:work.reduce((n,w)=>n+Number(w.metrics.loan_repayments||0),0)};});return {start,end,events,reports,approved,groups};}
function transactionReportsView(){const {start,end,events,reports,approved,groups}=transactionReportData();return `<section class="card reports-panel">${reportFilters(false)}${reportPeriodControls()}<div class="report-actions"><p class="smalltext">${S.reportFrequency} · ${e(start)} – ${e(end)}</p><button type="button" class="outline small" onclick="exportTransactions()">Export CSV</button></div><div class="report-metrics">${[['CMS activities',events.length],['BM-approved staff reports',approved.length],['Awaiting BM',reports.filter(w=>w.status==='For review').length],['Draft / returned',reports.filter(w=>['Draft','Returned'].includes(w.status)).length]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><h2>Branch transactions</h2><div class="table-wrap report-table"><table><thead><tr><th>Branch</th><th>CMS activities</th><th>Approved work reports</th><th>Savings collected</th><th>Loans released</th><th>Loan repayments</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${e(bn(g.branch))}<small>District ${g.district}</small></td><td>${g.events}</td><td>${g.staffReports}</td><td>${money(g.collections)}</td><td>${money(g.releases)}</td><td>${money(g.repayments)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Cash transaction totals come from BM-approved staff reports for the selected frequency and exact period. Daily, weekly and monthly summaries are kept separate to prevent counting the same transactions twice. CMS activities count recorded application actions.</p><h2 class="spacer">Overall report status</h2>${reportStatusOverview()}<h2 class="spacer">Recorded CMS transactions</h2>${auditRows(events,'transactions')}</section>`;}
function reportStatusOverview(){const reports=S.reports.filter(r=>!r.archived_at&&(S.reportDistrict==='all'||r.district===Number(S.reportDistrict))&&(S.reportBranch==='all'||r.branch_id===S.reportBranch)&&(S.scope==='all'||r.branch_id===S.scope)),work=filteredWorkReports();return `<div class="report-status-overview">${['Draft','For review','Approved','Returned','Filed'].map(status=>`<div><span>${status}</span><strong>${reports.filter(r=>r.status===status&&S.reportTypes.find(t=>t.id===r.type_id)?.category!=='Work').length+work.filter(w=>w.status===status).length}</strong></div>`).join('')}</div><p class="hint">Governance register status covers the selected location; staff work status covers the selected daily, weekly or monthly period.</p>`;}
function exportTransactions(){if(!canUseReports()||S.role==='Staff')return;const d=transactionReportData();downloadCsv([['Frequency','Period start','Period end','District','Branch','CMS activities','BM-approved staff reports','Savings collected','Loans released','Loan repayments'],...d.groups.map(g=>[S.reportFrequency,d.start,d.end,g.district,bn(g.branch),g.events,g.staffReports,g.collections,g.releases,g.repayments])],'OCCCI-'+S.reportFrequency+'-transactions-'+d.start+'.csv');}
function staffWorkView(own=true){const headingHtml=own?heading('My reports',`${e(S.me?.full_name||'Staff')} · ${e(bn(S.assignment?.branch_id))} branch · Submit work reports to your Branch Manager.`):'';if(!S.reportsReady)return headingHtml+`<section class="card"><h2>Work reports need activation</h2><p>${e(S.reportsError||'Refresh to load reporting records.')}</p>${button('Retry','reload()','primary')}</section>`;const rows=filteredWorkReports().filter(w=>!own||w.created_by===S.session.user.id),pages=Math.max(1,Math.ceil(rows.length/20));S.reportPage=Math.min(Math.max(1,S.reportPage),pages);return headingHtml+`<section class="card reports-panel">${own?'':reportFilters(false)}${reportPeriodControls()}<div class="report-actions"><p class="smalltext">${rows.length} work reports · 20 per page</p>${S.role==='Staff'?'<button type="button" class="primary small" onclick="workEditDialog()">'+icon('plus')+' New work report</button>':''}</div><div class="report-status-overview">${['Draft','For review','Approved','Returned'].map(status=>`<div><span>${status==='For review'?'Awaiting BM':status}</span><strong>${rows.filter(w=>w.status===status).length}</strong></div>`).join('')}</div><ul class="request-list">${rows.slice((S.reportPage-1)*20,S.reportPage*20).map(w=>`<li class="request-list-row"><div class="request-list-info"><div class="request-list-title"><h2>${e(w.title)}</h2>${statusPill(w.status)}</div><p class="request-list-meta">${e(S.profiles.find(p=>p.id===w.created_by)?.full_name||'OCCCI Staff')} · ${e(bn(w.branch_id))} · ${e(w.period_start)} – ${e(w.period_end)}</p></div><button type="button" class="outline request-list-action" onclick="workDialog('${w.id}')">View report</button></li>`).join('')}</ul>${rows.length?'':empty('No work reports in this period','Choose another period or create your work report.')}<nav class="pagination"><span>Page ${S.reportPage} of ${pages}</span><div class="flex"><button type="button" class="outline small" onclick="S.reportPage--;render()" ${S.reportPage===1?'disabled':''}>Previous</button><button type="button" class="outline small" onclick="S.reportPage++;render()" ${S.reportPage===pages?'disabled':''}>Next</button></div></nav></section>`;}
function workEditDialog(id=''){if(S.role!=='Staff')return;const w=S.workReports.find(w=>w.id===id);if(w&&(w.created_by!==S.session.user.id||!['Draft','Returned'].includes(w.status)))return;const period=reportPeriod(w?.frequency||S.reportFrequency,w?.period_start||S.reportOn);openModal(id?'Edit my work report':'New work report',`<form onsubmit="event.preventDefault();saveWorkReport(this,'${id}')"><p class="hint">${e(bn(S.assignment.branch_id))} branch · ${e(S.me.full_name)} · Reviewed by your BM</p><div class="form-grid"><label>Frequency<select name="frequency" onchange="workFormPeriodChanged(this.form)">${memberFilterOptions(['Daily','Weekly','Monthly'].map(v=>[v,v]),w?.frequency||S.reportFrequency)}</select></label>${field('Title','title',w?.title||S.reportFrequency+' branch work report')}${field('Period start','period_start',w?.period_start||period.start,'date')}${field('Period end','period_end',w?.period_end||period.end,'date')}<label class="full">Work summary<textarea name="summary" maxlength="10000" rows="3">${e(w?.summary||'')}</textarea></label>${Object.entries(workMetricLabels).map(([k,label])=>field(label,k,w?.metrics?.[k]??'','number',false)).join('')}${supportingDocumentsPicker()}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required rows="2"></textarea></label></div><p class="hint">Enter actual totals from your original records. Save a draft, then submit it to BM. Approved reports are published to the cooperative report register.</p><button type="submit" class="primary">Save draft</button></form>`);const form=$('modalContent').querySelector('form');form.elements.period_start.setAttribute('onchange','workFormPeriodChanged(this.form)');form.elements.period_end.readOnly=true;form._supportingDocuments=(w?.documents||[]).slice();renderSelectedDocuments(form);}
function workFormPeriodChanged(form){const p=reportPeriod(form.elements.frequency.value,form.elements.period_start.value);form.elements.period_start.value=p.start;form.elements.period_end.value=p.end;}
async function saveWorkReport(form,id){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const v=Object.fromEntries(new FormData(form)),files=selectedDocuments(form).slice();if(files.length)validateDocuments(files);form.dataset.uploading='true';renderSelectedDocuments(form);const documents=[];for(const file of files)documents.push(file.path?file:{path:await upload('occci-reports',file),name:file.name,size:file.size,type:file.type||'application/octet-stream'});const metrics=Object.fromEntries(Object.keys(workMetricLabels).filter(k=>v[k]!=='').map(k=>[k,Number(v[k])]));const r=S.workReports.find(w=>w.id===id);const result=await rpc('occci_save_work_report',{target:id||null,expected_revision:r?.revision||0,values_json:{frequency:v.frequency,title:v.title,period_start:v.period_start,period_end:v.period_end,summary:v.summary,metrics,documents},reason:v.reason});closeModal();await loadReports();render();workDialog(result);toast('Work report saved and logged.');}catch(err){$('actionMessage').textContent=err.message;}finally{form.dataset.uploading='false';renderSelectedDocuments(form);btn.disabled=false;}}
function workDialog(id){const w=S.workReports.find(w=>w.id===id);if(!w)return;const own=w.created_by===S.session.user.id&&S.role==='Staff',review=S.role==='BM'&&w.branch_id===S.assignment.branch_id&&w.status==='For review';openModal(w.title,`<div class="report-detail-head">${statusPill(w.status)}<span>${e(bn(w.branch_id))} · ${e(w.frequency)}</span><button type="button" class="outline small" onclick="workHistoryDialog('${id}')">${icon('clock')} Activity logs</button></div><p class="smalltext">${e(S.profiles.find(p=>p.id===w.created_by)?.full_name||'OCCCI Staff')} · ${e(w.period_start)} – ${e(w.period_end)}</p><p class="content-body">${e(w.summary||'Draft summary not recorded.')}</p><dl class="details-list">${Object.entries(w.metrics).map(([k,v])=>detail(e(workMetricLabels[k]||k),['savings_collections','loan_releases','loan_repayments'].includes(k)?money(v):e(v))).join('')}</dl>${w.review_note?`<p class="hint">BM notes: ${e(w.review_note)}</p>`:''}<ul class="document-list">${w.documents.map((d,i)=>`<li><button type="button" class="outline small" onclick="viewWorkDocument('${id}',${i})">${icon('file')}${e(d.name)}</button><small>${(d.size/1024/1024).toFixed(2)} MB</small></li>`).join('')}</ul><div class="priority-actions">${own&&['Draft','Returned'].includes(w.status)?`<button type="button" class="outline" onclick="workEditDialog('${id}')">Edit draft</button><button type="button" class="primary" onclick="workDecisionDialog('${id}','Submit')">Send to BM</button>`:''}${review?`<button type="button" class="primary" onclick="workDecisionDialog('${id}','Approve')">Approve and publish</button><button type="button" class="outline" onclick="workDecisionDialog('${id}','Return')">Return for correction</button>`:''}${w.published_report&&S.role!=='Staff'?`<button type="button" class="outline" onclick="reportDialog('${w.published_report}')">View approved register record</button>`:''}</div>`);}
function workDecisionDialog(id,decision){const w=S.workReports.find(w=>w.id===id);openModal(decision==='Submit'?'Send work report to BM':decision+' staff work report',`<form onsubmit="event.preventDefault();transitionWorkReport(this,'${id}','${decision}',${w.revision})"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="hint">${decision==='Approve'?'Approval publishes this report to the branch, district and Admin reporting register.':'The report and this action remain in the work activity log.'}</p><button type="submit" class="primary">${decision==='Submit'?'Send to BM':'Record decision'}</button></form>`);}
async function transitionWorkReport(form,id,decision,revision){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await rpc('occci_work_report_transition',{target:id,decision,expected_revision:revision,reason:new FormData(form).get('reason')});closeModal();await loadReports();render();workDialog(id);toast('Work report action recorded.');}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
function workHistoryDialog(id){openModal('Staff work activity logs',`<button type="button" class="outline small" onclick="workDialog('${id}')">Back to work report</button><div class="spacer">${auditRows(S.workReportEvents.filter(a=>a.work_report_id===id),'work:'+id)}</div>`);}
async function viewWorkDocument(id,index){const file=S.workReports.find(w=>w.id===id)?.documents[index];if(!file)return;try{const url=await signedUrl('occci-reports',file.path),a=document.createElement('a');a.href=url+(url.includes('?')?'&':'?')+'download='+encodeURIComponent(file.name);a.download=file.name;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(err){$('actionMessage').textContent=err.message;}}
